CustomField.formula:
if( 
TVM_Sales_Month_Filter_Month_Completed__c = AddMonths(TVM_Sales_Month_Static_Completed__c, 0),
"Current Month|",

if(
TVM_Sales_Month_Filter_Month_Completed__c = AddMonths(TVM_Sales_Month_Static_Completed__c, 1),
"Last Month|",

if(
TVM_Sales_Month_Filter_Month_Completed__c = AddMonths(TVM_Sales_Month_Static_Completed__c, 2),
"2 Months Ago|",

if(
TVM_Sales_Month_Filter_Month_Completed__c = AddMonths(TVM_Sales_Month_Static_Completed__c, 3),
"3 Months Ago|",
""
))))& 

if( YEAR(TODAY()) = YEAR(TVM_Sales_Month_Static_Completed__c) , "YTD|",
if( YEAR(TODAY())-1 = YEAR(TVM_Sales_Month_Static_Completed__c) , "Last Year|",
"None"
))
& "Q"&Text(Ceiling(Month(TVM_Sales_Month_Static_Completed__c)/3))
/*
Current Quarter
Last Quarter
*/
